INSERT INTO trivia_questions (topic, level, type, prompt, payload, perishable, status, verification)
VALUES
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'What is the capital city of California?', '{"options":["Los Angeles","San Francisco","Sacramento","San Diego"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Sacramento has been the capital of California since 1854; all other options are major cities but not the capital."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'Which U.S. state has Juneau as its capital city?', '{"options":["Hawaii","Alaska","Montana","Washington"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Juneau is unambiguously the capital of Alaska; the other options (Hawaii''s capital is Honolulu, Montana''s is Helena, Washington''s is Olympia) are all clearly wrong."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'Austin is the capital of which U.S. state?', '{"options":["Oklahoma","New Mexico","Arizona","Texas"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Austin is definitively the capital of Texas; the other options (Oklahoma City, Santa Fe, Phoenix) are the capitals of their respective states, making all distractors clearly wrong."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'What is the capital of Florida?', '{"options":["Miami","Orlando","Tallahassee","Jacksonville"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Tallahassee is definitively the capital of Florida; all other options (Miami, Orlando, Jacksonville) are major cities but not the capital."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'Which city is the capital of New York State?', '{"options":["New York City","Buffalo","Albany","Syracuse"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Albany has been the capital of New York State since 1797; the other options (New York City, Buffalo, Syracuse) are all clearly wrong."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'Honolulu is the capital of which U.S. state?', '{"options":["Guam","Hawaii","California","Florida"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Honolulu is unambiguously the capital (and largest city) of Hawaii; all other options are clearly wrong (Guam is a U.S. territory, not a state; California''s capital is Sacramento; Florida''s capital is Tallahassee)."}'::jsonb),
  ('U.S. states and their capitals', 'younger_kid', 'mc', 'What is the capital city of Colorado?', '{"options":["Boulder","Colorado Springs","Fort Collins","Denver"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Denver is unambiguously the capital of Colorado; all other options (Boulder, Colorado Springs, Fort Collins) are cities in Colorado but not the capital."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'How many planets are in our solar system?', '{"options":["7","8","9","10"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Since the IAU''s 2006 redefinition, there are officially 8 planets in our solar system; all other options are clearly wrong."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'Which planet is the largest in our solar system?', '{"options":["Saturn","Neptune","Earth","Jupiter"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Jupiter is unambiguously the largest planet in our solar system, and all three wrong options (Saturn, Neptune, Earth) are clearly not the largest."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'What is the name of the galaxy that our solar system lives in?', '{"options":["Andromeda","The Milky Way","The Whirlpool","Triangulum"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Our solar system is definitively located in the Milky Way galaxy; all other options (Andromeda, Whirlpool, Triangulum) are distinct, separate galaxies."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'Which planet is known for having a giant ring system made mostly of ice and rock?', '{"options":["Uranus","Mars","Saturn","Jupiter"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Saturn is definitively known for its spectacular, giant ring system composed mostly of ice and rock particles; while Uranus and Jupiter also have rings, they are faint and not \"giant,\" and Mars has no rings at all."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'About how long does it take for light from the Sun to reach Earth?', '{"options":["About 8 seconds","About 8 minutes","About 8 hours","About 8 days"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Light travels from the Sun to Earth in approximately 8 minutes and 20 seconds (~499 seconds), making \"About 8 minutes\" correct; all other options are clearly wrong by orders of magnitude."}'::jsonb),
  ('The solar system, planets, and space', 'younger_kid', 'mc', 'Which planet is called the Red Planet because of its reddish color?', '{"options":["Venus","Mercury","Neptune","Mars"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mars is universally known as the Red Planet due to iron oxide (rust) on its surface; all other options are clearly wrong."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'What is 7 times 8?', '{"options":["54","56","63","48"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"7 × 8 = 56; all distractors (54, 63, 48) are clearly wrong — they are products of other single-digit pairs (6×9, 7×9, 6×8) but not 7×8."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'If you divide 72 by 9, what do you get?', '{"options":["7","6","8","9"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"72 ÷ 9 = 8, and all other options (7, 6, 9) are clearly incorrect."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'Which multiplication fact belongs to the same fact family as 6 ÷ 2 = 3?', '{"options":["2 × 4 = 8","3 × 3 = 9","2 × 3 = 6","6 × 1 = 6"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The fact family for 6 ÷ 2 = 3 uses the numbers 2, 3, and 6; the related multiplication facts are 2 × 3 = 6 and 3 × 2 = 6, and only option 2 (2 × 3 = 6) matches. All other options use different number sets and are clearly wrong."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'A baker puts 6 cookies on each tray. If she fills 9 trays, how many cookies does she have in all?', '{"options":["45","48","54","63"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"6 × 9 = 54, and all other options (45, 48, 63) are clearly incorrect."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'What is the missing number? 8 × __ = 64', '{"options":["6","7","9","8"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"8 × 8 = 64 is correct, and all other options (6, 7, 9) are clearly wrong: 8×6=48, 8×7=56, 8×9=72."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'A box of crayons has 96 crayons split equally into 12 rows. How many crayons are in each row?', '{"options":["6","7","8","9"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"96 ÷ 12 = 8, confirming option 2 is correct; all other options (6, 7, 9) are clearly wrong."}'::jsonb),
  ('Multiplication and division facts', 'younger_kid', 'mc', 'Which of these numbers is a product of both 4 and 6 — meaning it appears in BOTH the 4 times table and the 6 times table?', '{"options":["16","18","20","24"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"24 = 4×6 = 6×4, and it appears in both the 4 times table (4×6) and the 6 times table (6×4); the other options — 16 (only in the 4s), 18 (only in the 6s), and 20 (only in the 4s/5s) — are correctly wrong."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'What do we call scientists who dig up and study dinosaur bones and fossils?', '{"options":["Archaeologists","Paleontologists","Geologists","Biologists"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Paleontologists are definitively the scientists who study fossils and dinosaur bones; the other options (archaeologists study human artifacts, geologists study rocks/earth, biologists study living organisms) are all clearly wrong."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'Which dinosaur is famous for having three horns on its face and a large bony frill around its neck?', '{"options":["Stegosaurus","Ankylosaurus","Triceratops","Parasaurolophus"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Triceratops is definitively known for its three facial horns and large bony frill; all other options are clearly wrong (Stegosaurus has back plates, Ankylosaurus has armored body/tail club, Parasaurolophus has a head crest)."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'Dinosaurs are classified as reptiles. Which of the following animals alive today is most closely related to dinosaurs?', '{"options":["Crocodiles","Lizards","Turtles","Birds"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Birds are avian dinosaurs (theropod descendants), making them the closest living relatives of non-avian dinosaurs; crocodiles are the next closest but still far more distant, and lizards/turtles are even less related."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'The massive asteroid impact believed to have wiped out the non-bird dinosaurs happened about how many million years ago?', '{"options":["250 million years ago","66 million years ago","10 million years ago","150 million years ago"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Cretaceous-Paleogene (K-Pg) extinction event, caused by the Chicxulub asteroid impact, occurred approximately 66 million years ago, wiping out non-avian dinosaurs; all other options are clearly incorrect."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'Stegosaurus had a double row of large bony plates running along its back. What do scientists think those plates were mainly used for?', '{"options":["Storing food","Digging underground burrows","Temperature regulation and display","Carrying its young"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Scientists widely agree that Stegosaurus''s dorsal plates were primarily used for thermoregulation (the plates were highly vascularized) and visual display/species recognition, making option 2 correct; the other options are clearly implausible."}'::jsonb),
  ('Dinosaurs and prehistoric life', 'younger_kid', 'mc', 'Which prehistoric creature was NOT a dinosaur but was a giant flying reptile that lived at the same time as dinosaurs?', '{"options":["Pterodactyl","Velociraptor","Brachiosaurus","Iguanodon"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Pterodactyl (a pterosaur) was indeed a flying reptile and not a dinosaur, while Velociraptor, Brachiosaurus, and Iguanodon are all true dinosaurs — all distractors are clearly wrong options."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In Minecraft, what material do you need to craft a torch?', '{"options":["Wood and iron","Coal and a stick","Stone and string","Sand and gravel"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Minecraft, a torch is crafted by placing a coal (or charcoal) on top of a stick, making option 1 correct; all other options are clearly wrong crafting combinations."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In Minecraft, what is the name of the final boss that lives in The End dimension?', '{"options":["The Wither","The Ender Dragon","The Elder Guardian","The Blaze"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Ender Dragon is definitively the final boss residing in The End dimension in Minecraft; the other options are bosses found elsewhere (The Wither is summoned in the overworld/nether, The Elder Guardian lives in ocean monuments, and The Blaze is a nether mob), making all distractors clearly wrong."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In the game Super Mario Bros., what is the name of the princess that Mario is always trying to rescue?', '{"options":["Princess Daisy","Princess Rosalina","Princess Zelda","Princess Peach"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Super Mario Bros., Mario rescues Princess Peach (also known as Princess Toadstool); the distractors are all clearly wrong — Daisy is associated with Sarasaland, Rosalina with the cosmos/Comet Observatory, and Zelda is from a completely different Nintendo franchise."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In Minecraft, which dangerous mob only attacks you if you look directly into its eyes?', '{"options":["Creeper","Zombie","Enderman","Skeleton"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Endermen are neutral mobs that only become hostile when a player looks directly at their eyes (upper body/face), which is a well-known and unique Minecraft mechanic; the other options (Creeper, Zombie, Skeleton) are all hostile mobs that attack regardless of eye contact."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In the Pokémon video games, what element does the starter Pokémon Charmander represent?', '{"options":["Water","Grass","Electric","Fire"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Charmander is unambiguously a Fire-type starter Pokémon, and all three distractors (Water, Grass, Electric) are clearly incorrect."}'::jsonb),
  ('Minecraft and popular video games', 'younger_kid', 'mc', 'In Minecraft, what happens when a Creeper gets close to you and starts flashing white?', '{"options":["It turns friendly and follows you","It explodes","It teleports away","It drops diamonds"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Minecraft, a Creeper flashing white is its ignition/fuse animation, after which it detonates in an explosion; all other options are clearly incorrect behaviors."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'What is the very first Pokémon listed in the original Pokédex — number 001?', '{"options":["Charmander","Bulbasaur","Squirtle","Pikachu"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Bulbasaur is definitively #001 in the original National Pokédex; all other options (Charmander #004, Squirtle #007, Pikachu #025) are clearly wrong."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'What type of Pokémon is Pikachu?', '{"options":["Fire","Water","Electric","Grass"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Pikachu is definitively an Electric-type Pokémon, and all three wrong options (Fire, Water, Grass) are clearly incorrect."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'Into which Pokémon does Caterpie evolve after becoming a Metapod?', '{"options":["Beautifly","Butterfree","Beedrill","Venomoth"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Caterpie evolves into Metapod, then into Butterfree; all distractors are clearly wrong (Beautifly evolves from Silcoon, Beedrill from Kakuna, Venomoth from Venonat)."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'What is the name of Ash''s main rival in the original Pokémon anime series?', '{"options":["Brock","Misty","Gary","Tracey"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Gary Oak is clearly Ash''s main rival in the original Pokémon anime; Brock and Misty are companions, and Tracey is also a travel companion, making all distractors clearly wrong."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'Which legendary Pokémon is known as ''the Genetic Pokémon'' and was created through gene-splicing experiments?', '{"options":["Mew","Lugia","Mewtwo","Arceus"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mewtwo is indeed officially classified as ''the Genetic Pokémon'' and its lore states it was created by scientists through gene-splicing experiments on Mew''s DNA; the other options (Mew, Lugia, Arceus) are clearly wrong for this description."}'::jsonb),
  ('Pokémon', 'younger_kid', 'mc', 'Which item do you need to make Eevee evolve into Flareon?', '{"options":["Water Stone","Thunder Stone","Fire Stone","Leaf Stone"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Using a Fire Stone on Eevee evolves it into Flareon; Water Stone gives Vaporeon, Thunder Stone gives Jolteon, and Leaf Stone does not evolve Eevee at all — all distractors are clearly wrong."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'Which famous statue, given to the United States by France, stands in New York Harbor holding a torch high in the air?', '{"options":["The Lincoln Memorial","The Statue of Liberty","The Washington Monument","The Liberty Bell"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Statue of Liberty was indeed a gift from France, stands in New York Harbor, and holds a torch aloft; all distractors are clearly wrong landmarks."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'Mount Rushmore is a giant sculpture carved into a mountain. Which U.S. state is it located in?', '{"options":["Wyoming","Colorado","Montana","South Dakota"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mount Rushmore is definitively located in the Black Hills of South Dakota; all other options are clearly incorrect neighboring states."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'The bald eagle is an important American symbol. It appears on the Great Seal of the United States, but what is the Great Seal mainly used for?', '{"options":["To decorate the President''s bedroom","To officially stamp and approve important government documents","To mark the entrance of the White House","To design U.S. postage stamps"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Great Seal of the United States is used to authenticate certain official documents of the U.S. government, such as treaties, presidential proclamations, and letters of credence; the other options are clearly incorrect."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'The Liberty Bell is a famous American symbol of freedom. In which city can you visit it today?', '{"options":["Boston, Massachusetts","Washington, D.C.","Philadelphia, Pennsylvania","New York City, New York"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Liberty Bell is housed at the Liberty Bell Center in Philadelphia, Pennsylvania, and the other three options are clearly incorrect."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'The American flag has 50 stars on it. What do those 50 stars represent?', '{"options":["The 50 most important American cities","The 50 U.S. states","The 50 years since independence","The 50 members of the first Congress"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Each star on the U.S. flag represents one of the 50 states, a well-established fact; all other options are clearly incorrect."}'::jsonb),
  ('American symbols and famous landmarks', 'younger_kid', 'mc', 'The Grand Canyon is one of America''s most famous natural landmarks. Which river carved out the Grand Canyon over millions of years?', '{"options":["The Mississippi River","The Missouri River","The Rio Grande","The Colorado River"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Colorado River is definitively the river that carved the Grand Canyon; all other options are clearly wrong rivers located in different regions."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Harry Potter and the Sorcerer''s Stone,'' what sport do students play while riding broomsticks at Hogwarts?', '{"options":["Quidditch","Bludgerball","Broomstick Racing","Wizardball"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Quidditch is unambiguously the broomstick sport played at Hogwarts; the other options (Bludgerball, Broomstick Racing, Wizardball) are fictional distractors that do not exist in the Harry Potter universe as sports."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Percy Jackson and the Lightning Thief,'' which god of the sea is Percy Jackson''s father?', '{"options":["Zeus","Hades","Poseidon","Apollo"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Percy Jackson and the Lightning Thief, Percy''s father is indeed Poseidon, the Greek god of the sea; all other options (Zeus, Hades, Apollo) are clearly wrong."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Charlotte''s Web,'' what is the name of the pig that Charlotte the spider works so hard to save?', '{"options":["Babe","Wilbur","Waldo","Chester"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In E.B. White''s ''Charlotte''s Web,'' the pig''s name is definitively Wilbur; the distractors (Babe from a different story, Waldo, and Chester) are all clearly wrong."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Harry Potter,'' what is the name of the house at Hogwarts that Harry Potter is sorted into?', '{"options":["Slytherin","Hufflepuff","Ravenclaw","Gryffindor"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Harry Potter is unambiguously sorted into Gryffindor by the Sorting Hat in his first year at Hogwarts; all other options are real houses but clearly wrong for this question."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Percy Jackson and the Lightning Thief,'' what is the name of the special summer camp where young demigods go to train?', '{"options":["Camp Half-Blood","Camp Jupiter","Camp Olympus","Camp Demigod"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Camp Half-Blood is clearly the correct answer from the first Percy Jackson book; Camp Jupiter appears in the later \"Heroes of Olympus\" series (not this book), and the other options don''t exist in the series, making all distractors clearly wrong."}'::jsonb),
  ('Kids'' books: Percy Jackson, Harry Potter, and Charlotte''s Web', 'younger_kid', 'mc', 'In ''Charlotte''s Web,'' what is the very first word that Charlotte weaves into her web to describe Wilbur?', '{"options":["Terrific","Radiant","Humble","Some Pig"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In E.B. White''s ''Charlotte''s Web,'' the first word Charlotte weaves into her web is indeed \"Some Pig,\" followed later by \"Terrific,\" \"Radiant,\" and \"Humble,\" making all distractors clearly wrong."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'Which ancient Egyptian structure was built as a tomb for the pharaoh Khufu and is one of the Seven Wonders of the Ancient World?', '{"options":["The Sphinx","The Great Pyramid of Giza","The Parthenon","The Colosseum"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Great Pyramid of Giza was indeed built as a tomb for Pharaoh Khufu (~2560 BCE) and is the only surviving Wonder of the Seven Wonders of the Ancient World; the other options (Sphinx, Parthenon, Colosseum) are clearly wrong — the Sphinx is not a tomb nor a Wonder, the Parthenon is Greek, and the Colosseum is Roman."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'In ancient Greece, what was the name of the city-state famous for training its citizens to be fierce soldiers from a very young age?', '{"options":["Athens","Corinth","Sparta","Thebes"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Sparta is universally recognized as the ancient Greek city-state famous for its rigorous military training (the agoge) beginning in early childhood; the other options (Athens, Corinth, Thebes) are clearly wrong for this description."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'Ancient Egyptians used a system of picture-based writing called what?', '{"options":["Cuneiform","Sanskrit","Hieroglyphics","Latin"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Ancient Egyptian picture-based writing is definitively called hieroglyphics; the distractors (Cuneiform = Mesopotamian wedge script, Sanskrit = ancient Indian language, Latin = Roman language) are all clearly wrong."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'Which Roman structure, completed around 80 AD, was a giant oval arena used for gladiator fights and public spectacles?', '{"options":["The Pantheon","The Forum","The Circus Maximus","The Colosseum"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Colosseum (Flavian Amphitheatre) was completed around 80 AD, is elliptical/oval in shape, and was the primary venue for gladiatorial contests and public spectacles; the other options are clearly wrong — the Pantheon is a temple, the Forum is a public square, and the Circus Maximus is a chariot-racing track, not an oval arena for gladiators."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'In Greek mythology, who was the king of the gods and ruler of Mount Olympus?', '{"options":["Poseidon","Apollo","Hades","Zeus"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Zeus is unambiguously the king of the gods and ruler of Mount Olympus in Greek mythology; all distractors (Poseidon, Apollo, Hades) are clearly incorrect for this title."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'Ancient Egyptians preserved the bodies of their dead rulers through a process called what?', '{"options":["Cremation","Mummification","Fossilization","Embalming in wax"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mummification is the well-established term for the ancient Egyptian preservation process; all distractors are clearly incorrect methods (cremation uses fire, fossilization is a geological process, and wax embalming is not an Egyptian practice)."}'::jsonb),
  ('Ancient Egypt, Greece, and Rome', 'older_kid', 'mc', 'Julius Caesar was a famous leader of which ancient civilization?', '{"options":["Ancient Egypt","Ancient Greece","Ancient Persia","Ancient Rome"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Julius Caesar was unambiguously a Roman general and statesman; all other options are clearly wrong civilizations."}'::jsonb),
  ('World rivers, mountains, and deserts', 'older_kid', 'mc', 'On which continent is the Sahara Desert located?', '{"options":["Asia","Australia","South America","Africa"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Sahara Desert is unambiguously located in Africa, and all three wrong options (Asia, Australia, South America) are clearly incorrect."}'::jsonb),
  ('World rivers, mountains, and deserts', 'older_kid', 'mc', 'What is the name of the tallest mountain in the world?', '{"options":["K2","Mount Kilimanjaro","Mount Everest","Mount McKinley"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mount Everest at 8,849 m is unambiguously the tallest mountain in the world by elevation above sea level; all three distractors are clearly incorrect for this criterion."}'::jsonb),
  ('World rivers, mountains, and deserts', 'older_kid', 'mc', 'The Amazon River flows through which continent?', '{"options":["Africa","North America","Asia","South America"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Amazon River is definitively located in South America, flowing through Brazil, Peru, and Colombia; all other options are clearly incorrect continents."}'::jsonb),
  ('World rivers, mountains, and deserts', 'older_kid', 'mc', 'Which desert is the largest cold desert in the world?', '{"options":["Gobi Desert","Atacama Desert","Antarctic Desert","Patagonian Desert"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Antarctic Desert is the largest cold desert in the world at ~14.2 million km², and is also the largest desert of any type; the other options (Gobi, Atacama, Patagonian) are all smaller and none is a strong rival for this title."}'::jsonb),
  ('World rivers, mountains, and deserts', 'older_kid', 'mc', 'The Andes mountain range runs along the western side of which continent?', '{"options":["North America","Europe","Africa","South America"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Andes is definitively the mountain range running along the western coast of South America, and all other options are clearly incorrect."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'What is the value of −3 + (−5)?', '{"options":["−8","−2","2","8"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"−3 + (−5) = −8; all other options (−2, 2, 8) are clearly wrong and represent common arithmetic mistakes."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'On a number line, which direction do you move when you add a negative integer?', '{"options":["To the left","To the right","Upward","It stays in place"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Adding a negative integer is equivalent to subtracting a positive integer, which always moves you to the left on a standard number line; all distractors are clearly wrong."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'What is the absolute value of −17?', '{"options":["17","−17","0","1"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The absolute value of −17 is 17 (the distance from zero on the number line), and all other options are clearly incorrect."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'Solve for x: x + 9 = 4. What is x?', '{"options":["−5","5","13","−13"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"x + 9 = 4 → x = 4 − 9 = −5; all distractors (5, 13, −13) are clearly wrong."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'Which of the following correctly compares two integers using the greater-than or less-than symbol?', '{"options":["−6 < −2","−6 > −2","−6 = −2","−6 > 0"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"−6 is less than −2 on the number line, so −6 < −2 is the only correct comparison; all distractors are clearly false (−6 > −2, −6 = −2, and −6 > 0 are all wrong)."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'Solve for n: 3n = −21. What is n?', '{"options":["−7","7","−63","63"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"3n = −21 → n = −21/3 = −7; all distractors (7, −63, 63) are clearly wrong."}'::jsonb),
  ('Pre-algebra: integers and one-step equations', 'older_kid', 'mc', 'What is the result of subtracting a negative integer — for example, 5 − (−3)?', '{"options":["8","2","−8","−2"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"5 − (−3) = 5 + 3 = 8; all other options are clearly wrong, and the math is unambiguous."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'The U.S. Constitution is divided into sections called articles. How many original articles does it have?', '{"options":["5","7","10","12"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The original U.S. Constitution contains exactly 7 articles; all other options (5, 10, 12) are clearly incorrect."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'Which branch of the U.S. government is responsible for making the country''s laws?', '{"options":["The Executive Branch","The Judicial Branch","The Legislative Branch","The Military Branch"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Legislative Branch (Congress) is clearly established by Article I of the Constitution as the lawmaking body; all distractors are clearly wrong — the Executive enforces laws, the Judicial interprets them, and the Military is not a branch of government."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'Congress is made up of two parts, or ''chambers.'' What are they called?', '{"options":["The House of Lords and the Senate","The House of Representatives and the Senate","The Supreme Court and the House of Representatives","The Cabinet and the Congress"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The U.S. Congress is indeed bicameral, composed of the House of Representatives and the Senate; all distractors are clearly wrong (House of Lords is British, Supreme Court is judicial, Cabinet is executive)."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'The first ten amendments to the U.S. Constitution are known by what special name?', '{"options":["The Declaration of Rights","The Founding Principles","The Bill of Rights","The Articles of Freedom"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The first ten amendments to the U.S. Constitution are universally known as the Bill of Rights; all other options are plausible-sounding but incorrect names."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'Which branch of government includes the Supreme Court and is in charge of deciding whether laws follow the Constitution?', '{"options":["The Legislative Branch","The Executive Branch","The Electoral Branch","The Judicial Branch"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Judicial Branch, headed by the Supreme Court, is clearly and unambiguously responsible for interpreting the Constitution and determining whether laws comply with it; the distractors (Legislative, Executive, and the fictitious Electoral Branch) are all clearly wrong."}'::jsonb),
  ('The U.S. Constitution and branches of government', 'older_kid', 'mc', 'The idea of ''checks and balances'' in the U.S. government means that each branch can do what?', '{"options":["Collect taxes from citizens","Limit the power of the other branches","Choose the members of the other branches","Write its own set of laws"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Checks and balances is the foundational principle that each branch of government has the ability to limit or check the powers of the other branches, making option 1 clearly correct and all other options clearly wrong."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'Alexander Graham Bell is credited with inventing which communication device in 1876?', '{"options":["The telegraph","The telephone","The radio","The television"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Alexander Graham Bell was granted the patent for the telephone in 1876; the other options (telegraph - Morse, radio - Marconi/Tesla, television - Baird/Farnsworth) are clearly wrong."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'Which scientist developed the theory of gravity after supposedly observing an apple fall from a tree?', '{"options":["Galileo Galilei","Albert Einstein","Isaac Newton","Nikola Tesla"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Isaac Newton is universally credited with developing the theory of universal gravitation, famously inspired by the apple anecdote; all other options are clearly wrong for this question."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'Thomas Edison is best known for inventing a practical version of which everyday device?', '{"options":["The light bulb","The microwave oven","The steam engine","The printing press"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Edison is famously credited with developing the first practical incandescent light bulb in 1879; the other options are clearly wrong (microwave: Percy Spencer; steam engine: James Watt/Thomas Newcomen; printing press: Gutenberg)."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'Marie Curie was the first person to win two Nobel Prizes. In which two scientific fields did she win them?', '{"options":["Physics and Chemistry","Chemistry and Biology","Physics and Medicine","Biology and Chemistry"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Marie Curie won the 1903 Nobel Prize in Physics (shared with Pierre Curie and Henri Becquerel) and the 1911 Nobel Prize in Chemistry, making option 0 clearly correct and all other options clearly wrong."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'Which inventor created the World Wide Web in 1989, making it possible for people to share information over the internet?', '{"options":["Bill Gates","Steve Jobs","Tim Berners-Lee","Alan Turing"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Tim Berners-Lee proposed and developed the World Wide Web in 1989 at CERN; the other options (Gates, Jobs, Turing) had no role in its creation, making all distractors clearly wrong."}'::jsonb),
  ('Famous scientists and their inventions', 'older_kid', 'mc', 'The Wright Brothers, Orville and Wilbur, are famous for inventing and successfully flying the first powered what?', '{"options":["Hot air balloon","Helicopter","Rocket ship","Airplane"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Wright Brothers made their historic first powered airplane flight at Kitty Hawk in 1903; all other options are clearly incorrect inventions associated with different inventors."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'What is the perimeter of a rectangle that is 8 cm long and 5 cm wide?', '{"options":["13 cm","26 cm","40 cm","20 cm"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Perimeter = 2×(length + width) = 2×(8+5) = 2×13 = 26 cm; all distractors represent common errors (half-perimeter = 13, area = 40, semi-perimeter of wrong calc = 20) and are clearly wrong."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'What is the area of a triangle with a base of 10 inches and a height of 6 inches?', '{"options":["60 square inches","30 square inches","16 square inches","120 square inches"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Area of a triangle = ½ × base × height = ½ × 10 × 6 = 30 square inches; all distractors are clearly wrong (60 is base×height without the ½, 16 is base+height, 120 is double the correct answer)."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'A square has a side length of 9 meters. What is its area?', '{"options":["36 square meters","18 square meters","45 square meters","81 square meters"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Area of a square = side², so 9² = 81 square meters; all distractors (36, 18, 45) are clearly wrong."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'What is the volume of a rectangular box that is 4 cm long, 3 cm wide, and 5 cm tall?', '{"options":["47 cubic cm","24 cubic cm","60 cubic cm","120 cubic cm"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Volume of a rectangular box = length × width × height = 4 × 3 × 5 = 60 cubic cm; all distractors are clearly wrong."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'Which formula gives you the area of a circle, where r is the radius?', '{"options":["2 × π × r","π × r²","π × r³","2 × π × r²"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The area of a circle is definitively π × r²; option 0 is circumference, option 2 is nonsensical for circles, and option 3 is the lateral surface area of a cylinder of height r — all clearly wrong."}'::jsonb),
  ('Geometry: area, perimeter, and volume', 'older_kid', 'mc', 'A rectangular garden is 12 feet long and 7 feet wide. How many feet of fencing are needed to go all the way around it?', '{"options":["84 feet","19 feet","38 feet","48 feet"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The perimeter of a rectangle is 2×(length + width) = 2×(12 + 7) = 2×19 = 38 feet; all distractors are clearly wrong (84 is area×1, 19 is half the perimeter, 48 is an unrelated number)."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'Which city is the capital of Australia — not Sydney, but the city chosen as a compromise between the two rival cities of Sydney and Melbourne?', '{"options":["Brisbane","Canberra","Perth","Adelaide"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Canberra is indeed Australia''s capital, chosen as a compromise location between Sydney and Melbourne when Australia federated in 1901, with the other options (Brisbane, Perth, Adelaide) being clearly wrong."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'Naypyidaw is the capital of which country in Southeast Asia?', '{"options":["Thailand","Cambodia","Vietnam","Myanmar"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Naypyidaw has been the capital of Myanmar since 2006; the other options have distinct capitals (Bangkok, Phnom Penh, Hanoi), so all distractors are clearly wrong."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'What is the capital city of Brazil — a planned city built in the interior of the country and inaugurated in 1960?', '{"options":["Rio de Janeiro","São Paulo","Brasília","Salvador"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Brasília is indeed Brazil''s capital, a planned city inaugurated on April 21, 1960; the other options (Rio de Janeiro, São Paulo, Salvador) are all major Brazilian cities but none is the current capital, making the distractors clearly wrong."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'Nur-Sultan, recently renamed Astana, is the capital of which large country in Central Asia?', '{"options":["Uzbekistan","Kazakhstan","Kyrgyzstan","Tajikistan"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Astana (renamed from Nur-Sultan in 2022, which itself had been renamed from Astana in 2019) is indeed the capital of Kazakhstan, the largest country in Central Asia; all other options are clearly wrong."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'Which African country has Dodoma as its official capital city?', '{"options":["Kenya","Uganda","Tanzania","Ethiopia"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Dodoma is indeed the official capital of Tanzania; the other options (Kenya - Nairobi, Uganda - Kampala, Ethiopia - Addis Ababa) are clearly wrong."}'::jsonb),
  ('World capitals (challenging)', 'older_kid', 'mc', 'Reykjavik is the world''s northernmost capital of a sovereign country. On which island nation is it located?', '{"options":["Greenland","Iceland","Norway","Faroe Islands"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Reykjavik is indeed the world''s northernmost capital of a sovereign country and is located in Iceland; Norway is not an island nation, Greenland is not a sovereign country, and the Faroe Islands are not a sovereign country either — all distractors are clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'The San Francisco Giants won three World Series championships in five years. Which years did they win all three titles?', '{"options":["2009, 2011, and 2013","2010, 2012, and 2014","2011, 2013, and 2015","2010, 2013, and 2016"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The San Francisco Giants won the World Series in 2010 (defeating the Texas Rangers), 2012 (defeating the Detroit Tigers), and 2014 (defeating the Kansas City Royals), confirming option 1 is correct and all other options are clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'Giants catcher Buster Posey won the National League Most Valuable Player award in which year?', '{"options":["2010","2012","2014","2016"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Buster Posey won the NL MVP award in 2012, batting .336 with 24 HR and 103 RBI; the other years listed are clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'Tim Lincecum was a two-time Cy Young Award winner for the Giants known for his wild pitching delivery. What nickname did fans give him?', '{"options":["The Franchise","The Freak","Big Time Timmy Jim","The Hammer"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Tim Lincecum was indeed widely nicknamed \"The Freak\" by fans and media due to his unorthodox, whip-like pitching delivery; the other options are clearly wrong nicknames for him."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'In 2021, the San Francisco Giants set a franchise record by winning how many regular-season games?', '{"options":["95","100","107","112"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The 2021 San Francisco Giants went 107-55, setting a franchise record for wins in a regular season, so option 2 (107) is correct and all other options are clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'The Giants play their home games at a ballpark right on San Francisco Bay. What is that stadium currently called?', '{"options":["Candlestick Park","Oracle Park","AT&T Center","Levi''s Stadium"],"correctIndex":1}'::jsonb, true, 'ready', '{"verdict":"ready","notes":"The San Francisco Giants'' home stadium on McCovey Cove (San Francisco Bay) is currently named Oracle Park (renamed from AT&T Park in 2019); Candlestick Park was a former SF venue (now demolished), AT&T Center is an arena in San Antonio, and Levi''s Stadium is the 49ers'' home in Santa Clara — all clearly wrong."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Michael Jackson''s ''Thriller'' album, released in 1982, became the best-selling album of all time. Which producer masterminded its recording alongside Jackson?', '{"options":["Nile Rodgers","Quincy Jones","Rick Rubin","David Foster"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Quincy Jones co-produced Thriller with Michael Jackson; the other options (Nile Rodgers, Rick Rubin, David Foster) had no involvement in the album, making all distractors clearly wrong."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Madonna''s 1989 music video for which song was famously condemned by the Vatican for its use of burning crosses and religious imagery?', '{"options":["Like a Prayer","Papa Don''t Preach","Material Girl","Express Yourself"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Madonna''s 1989 \"Like a Prayer\" video was indeed condemned by the Vatican for its controversial religious imagery, including burning crosses and a saint figure, and it led to Pepsi canceling their sponsorship deal with her; the other options are clearly wrong answers."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Which British synth-pop duo recorded the 1981 hit ''Don''t You Want Me,'' which spent five weeks at number one in the UK?', '{"options":["Soft Cell","Eurythmics","The Human League","Pet Shop Boys"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"\"Don''t You Want Me\" by The Human League was released in 1981 and spent five weeks at number one in the UK; the other options are all clearly different acts."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Nirvana''s 1991 album ''Nevermind'' famously displaced which artist''s album from the top spot on the Billboard 200 chart?', '{"options":["Garth Brooks","U2","Michael Jackson","Pearl Jam"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Nevermind reached #1 on the Billboard 200 in January 1992, displacing Garth Brooks'' \"Ropin'' the Wind\"; the other options are clearly wrong."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'The 1985 charity supergroup Band Aid released ''Do They Know It''s Christmas?'' to raise funds for famine relief in which country?', '{"options":["Sudan","Ethiopia","Somalia","Mozambique"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Band Aid''s ''Do They Know It''s Christmas?'' was released in 1984 (not 1985) to raise funds for the Ethiopian famine, but Ethiopia is unambiguously the correct country; the other options are clearly wrong."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Prince''s 1984 film and accompanying soundtrack album share the same title. What is that title?', '{"options":["Sign o'' the Times","Purple Rain","Around the World in a Day","Parade"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Prince''s 1984 semi-autobiographical film is titled \"Purple Rain,\" and the accompanying soundtrack album shares the same name; all other options are real Prince albums but are not associated with a 1984 film."}'::jsonb),
  ('1980s and 1990s pop music', 'adult', 'mc', 'Mariah Carey and which other artist originally recorded the 1994 duet ''Without You''? No — rather, ''Without You'' is a cover; which duo originally recorded it in 1970?', '{"options":["Simon & Garfunkel","The Everly Brothers","Badfinger","Crosby, Stills & Nash"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"\"Without You\" was written by Pete Ham and Tom Evans of Badfinger, and first recorded by them on their 1970 album \"No Dice\"; all other options are clearly wrong."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'Which classic rock album features the iconic tracks ''Stairway to Heaven,'' ''Black Dog,'' and ''Rock and Roll,'' yet was released with no title printed on its cover?', '{"options":["Led Zeppelin II","Led Zeppelin III","Led Zeppelin IV","Houses of the Holy"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Led Zeppelin''s fourth album (commonly called \"Led Zeppelin IV,\" \"Zoso,\" or \"Four Symbols\") was deliberately released in 1971 with no band name or title on its cover, and it contains all three named tracks; the other options are clearly wrong albums."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'The Who''s 1969 rock opera ''Tommy'' tells the story of a ''deaf, dumb, and blind kid'' who becomes a champion at which arcade game?', '{"options":["Pinball","Billiards","Chess","Darts"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Who''s ''Tommy'' famously features the song ''Pinball Wizard,'' in which the deaf, dumb, and blind boy Tommy becomes a pinball champion; all other options are clearly wrong."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'Pink Floyd''s ''The Dark Side of the Moon'' spent a record-breaking consecutive run on the Billboard 200 album chart. Approximately how many weeks did it chart in total across its various runs?', '{"options":["Around 400 weeks","Around 950 weeks","Around 200 weeks","Around 650 weeks"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Dark Side of the Moon has charted on the Billboard 200 for over 950 weeks total (as of recent counts, the number exceeds 950 and approaches/surpasses 1,000), making \"Around 950 weeks\" the closest and most defensible answer among the options; all other options are clearly too low or too high relative to the well-documented figure."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'Fleetwood Mac''s best-selling 1977 album ''Rumours'' was largely written and recorded while several band members were going through simultaneous romantic breakups with one another. What is the name of that album?', '{"options":["Tusk","Mirage","Rumours","Tango in the Night"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The question literally names the album (\"Rumours\") in its own text, making it trivially easy and a poor trivia question, but the proposed answer is factually correct and all distractors are genuine (but wrong) Fleetwood Mac albums."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'Before forming the Eagles, guitarist Glenn Frey and drummer Don Henley both served as backing musicians for which celebrated singer-songwriter?', '{"options":["James Taylor","Carole King","Linda Ronstadt","Carly Simon"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Glenn Frey and Don Henley were both part of Linda Ronstadt''s touring band in 1971 before they co-founded the Eagles; the other options (James Taylor, Carole King, Carly Simon) were not the employer who united them."}'::jsonb),
  ('Classic rock bands and albums', 'adult', 'mc', 'The Rolling Stones'' 1972 double album ''Exile on Main St.'' was recorded primarily in the basement of which guitarist''s rented villa in the South of France?', '{"options":["Mick Jagger''s","Bill Wyman''s","Brian Jones''s","Keith Richards''s"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Exile on Main St. was famously recorded in the basement of Villa Nellcôte, rented by Keith Richards in Villefranche-sur-Mer, France in 1971; all other options are clearly wrong."}'::jsonb),
  ('Famous novels and their authors', 'adult', 'mc', 'Which Russian author wrote the epic novel ''War and Peace'', published in its final form in 1869?', '{"options":["Fyodor Dostoevsky","Ivan Turgenev","Leo Tolstoy","Nikolai Gogol"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Leo Tolstoy wrote War and Peace, serialized 1865–1867 and published in its final book form in 1869; all other options are clearly wrong Russian authors."}'::jsonb),
  ('Famous novels and their authors', 'adult', 'mc', 'Gabriel García Márquez''s landmark novel ''One Hundred Years of Solitude'' follows multiple generations of which fictional family?', '{"options":["The Fermina family","The Buendía family","The Arcadio family","The Remedios family"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The novel unambiguously centers on the Buendía family of Macondo; the distractors use names of characters within the book (Fermina is from a different García Márquez novel, while Arcadio and Remedios are individual Buendía family members, not the family name itself), making them clearly wrong."}'::jsonb),
  ('Famous novels and their authors', 'adult', 'mc', 'Which American novelist wrote ''Beloved'', a Pulitzer Prize-winning story haunted by the legacy of slavery, published in 1987?', '{"options":["Alice Walker","Zora Neale Hurston","Maya Angelou","Toni Morrison"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Toni Morrison wrote ''Beloved'', published in 1987, which won the Pulitzer Prize for Fiction in 1988; the other options are notable authors but none wrote this work."}'::jsonb),
  ('Famous novels and their authors', 'adult', 'mc', 'Which 19th-century French author wrote ''Madame Bovary'', the story of a provincial doctor''s wife undone by romantic illusions and debt?', '{"options":["Honoré de Balzac","Victor Hugo","Émile Zola","Gustave Flaubert"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Gustave Flaubert published Madame Bovary in 1857; all three distractors (Balzac, Hugo, Zola) are clearly wrong authors for this work."}'::jsonb),
  ('Famous novels and their authors', 'adult', 'mc', 'Kazuo Ishiguro''s dystopian novel ''Never Let Me Go'', published in 2005, centers on young people raised at an English boarding school called what?', '{"options":["Brookfield","Hailsham","Chesil Hall","Pennhurst"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Ishiguro''s 2005 novel, the school where the cloned children are raised is definitively called Hailsham; the other options are not the name of any school in the novel."}'::jsonb),
  ('Movies: directors and Best Picture winners', 'adult', 'mc', 'Which director has won the most Academy Awards for Best Director, with four wins to his name?', '{"options":["John Ford","Steven Spielberg","William Wyler","Frank Capra"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"John Ford won four Best Director Oscars (The Informer, The Grapes of Wrath, How Green Was My Valley, The Quiet Man), more than any other director; Spielberg has 2, Wyler has 3, and Capra has 3, so all distractors are clearly wrong."}'::jsonb),
  ('Movies: directors and Best Picture winners', 'adult', 'mc', 'The 1972 Best Picture winner ''The Godfather'' was directed by which filmmaker?', '{"options":["Martin Scorsese","Francis Ford Coppola","Sidney Lumet","Brian De Palma"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Godfather (1972) was directed by Francis Ford Coppola and won the Academy Award for Best Picture; all other options are clearly wrong directors."}'::jsonb),
